package com.tanidikvar.api.discussion.service;import com.tanidikvar.api.common.dto.*;import com.tanidikvar.api.common.error.DomainException;import com.tanidikvar.api.discussion.dto.*;import com.tanidikvar.api.discussion.repository.DiscussionRepository;import java.util.*;import com.tanidikvar.api.question.service.QuestionAccessService;import com.tanidikvar.api.auth.service.AccountAccessService;import com.tanidikvar.api.profile.service.InteractionPolicy;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class DiscussionService{private final DiscussionRepository repository;private final QuestionAccessService questions;private final AccountAccessService accounts;private final InteractionPolicy interaction;
public DiscussionService(DiscussionRepository repository,QuestionAccessService questions,AccountAccessService accounts,InteractionPolicy interaction){this.repository=repository;this.questions=questions;this.accounts=accounts;this.interaction=interaction;}
private void writable(UUID answer,UUID user){
var parent=repository.questionId(answer).orElseThrow(()->new DomainException(404,"NOT_FOUND","Yanıt bulunamadı."));
var question=questions.lock(parent);accounts.lockActive(user);interaction.requireCompleted(user);
if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");
if(question.archivedAt()!=null)throw new DomainException(409,"QUESTION_ARCHIVED","Arşivlenmiş soruya katkı yapılamaz.");
}@Transactional public AnswerCommentResponse add(UUID answer,UUID user,AnswerCommentRequest request){writable(answer,user);if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");return repository.add(answer,user,request.body());}@Transactional(readOnly=true)public PageResponse<AnswerCommentResponse> list(UUID answer,int page,int size){SearchQuery.page(page,size);if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");return new PageResponse<>(repository.list(answer,page,size),page,size,repository.count(answer));}@Transactional public AnswerCommentResponse update(UUID answer,UUID comment,UUID user,AnswerCommentUpdateRequest request){writable(answer,user);if(!repository.visibleAnswer(answer))throw new DomainException(404,"NOT_FOUND","Yanıt bulunamadı.");var current=repository.comment(answer,comment).orElseThrow(()->new DomainException(404,"NOT_FOUND","Alt yorum bulunamadı."));if(!current.authorId().equals(user))throw new DomainException(403,"ACCESS_DENIED","Yalnız kendi alt yorumunu düzenleyebilirsin.");if(current.version()!=request.version())throw new DomainException(409,"STALE_VERSION","Alt yorum değişmiş; sayfayı yenile.");repository.update(comment,request.body());return repository.comment(answer,comment).orElseThrow();}@Transactional public void best(UUID question,UUID user,BestAnswerRequest request){if(!repository.best(question,request.answerId(),user))throw new DomainException(403,"BEST_ANSWER_NOT_ALLOWED","Yalnız soru sahibi görünür bir yanıtı seçebilir.");}@Transactional(readOnly=true)public List<QuestionTemplateResponse> templates(String category){return repository.templates(category==null?"":category.trim().toUpperCase(Locale.forLanguageTag("tr")));}}
